bg=7
patterns={
1:[[1,0,1],[1,0,1],[1,1,1]],
4:[[1,0,0],[1,1,0],[1,0,1]],
6:[[1,1,1],[0,1,0],[1,1,1]],
}
cols=[1,4,6]
out=[[bg]*19 for _ in range(7)]
for k,c in enumerate(cols):
    x=1+k*6
    # 5x5 outer filled
    for r in range(1,6):
        for j in range(5): out[r][x+j]=c
    # interior complement of matching 3x3 motif
    for i in range(3):
        for j in range(3):
            out[2+i][x+1+j]=bg if patterns[c][i][j] else c
print('\n'.join(' '.join(map(str,row)) for row in out))

bg=7
patterns={1:[[1,0,1],[1,0,1],[1,1,1]],4:[[1,0,0],[1,1,0],[1,0,1]],6:[[1,1,1],[0,1,0],[1,1,1]]}
colors=[1,4,6]
outv=[[bg]*7 for _ in range(19)]
for k,c in enumerate(colors):
    y=1+k*6
    for r in range(5):
        for j in range(5):outv[y+r][1+j]=c
    for i in range(3):
        for j in range(3):outv[y+1+i][2+j]=bg if patterns[c][i][j] else c
print('\n'.join(' '.join(map(str,r)) for r in outv))
